"use strict";
import { useLockContract } from "hooks/useLockContract";
import { useState } from "react";
import { ChevronDown } from "react-feather";
import styled from "styled-components";
import { Flex, Text, useMedia, useSporeColors } from "ui/src";
export default function AvailableAmoutAndBalancePercentage({
  title,
  onPercentageSelect
}) {
  const [showPercentage, setShowPercentage] = useState(false);
  const colors = useSporeColors();
  const media = useMedia();
  const { getFormattedABXBalance } = useLockContract();
  const userBalance = getFormattedABXBalance();
  const Button = styled.button`
    all: unset;
    padding: 2px 10px;
    background-color: ${colors.surface2Hovered.val};
    border-radius: 999px;
    cursor: pointer;
    transition: all 0.2s ease;
    &:hover {
      opacity: 0.7;
    }
  `;
  const tokenPercentage = ["10", "25", "50", "75", "100"];
  return <Flex>
      <Flex row justifyContent="space-between" gap={"$gap12"}>
        <Text variant={media.md ? "buttonLabel3" : "subheading2"}>{title}</Text>
        <Flex row justifyContent="space-between" gap={"$gap12"}>
          <Flex row justifyContent="space-between" gap={"$gap8"}>
            <Text variant={media.sm ? "body4" : "body3"} color={"$neutral2"}>
              Balance:
            </Text>
            <Text variant={media.sm ? "body4" : "body3"}>{userBalance || "0"} ABX</Text>
          </Flex>

          <Flex>
            <button
    role="button"
    type="button"
    className="button-clear"
    onClick={() => setShowPercentage(!showPercentage)}
  >
              <Flex
    py={"$spacing2"}
    px={"$spacing6"}
    backgroundColor={"$surface3"}
    borderRadius={"$rounded12"}
    row
    alignItems="center"
    gap={"$gap4"}
    $sm={{ px: "$spacing4" }}
  >
                <Text variant="body4" ml={2}>
                  %
                </Text>
                <Flex transform={[{ rotate: showPercentage ? "180deg" : "0deg" }]}>
                  <Flex>
                    <ChevronDown size={14} color={colors.neutral2.val} />
                  </Flex>
                </Flex>
              </Flex>
            </button>
          </Flex>
        </Flex>
      </Flex>

      {showPercentage && <Flex
    row
    justifyContent="space-between"
    gap={"$gap12"}
    alignItems="center"
    mt={"$spacing12"}
    pt={"$spacing16"}
    borderTopWidth={1}
    borderColor={"$surface3"}
    $md={{ justifyContent: "flex-end" }}
  >
          <Text variant="body3" color={"$neutral3"} $md={{ display: "none" }}>
            Select a share of your balance
          </Text>
          <Flex row justifyContent="space-between" gap={"$gap8"}>
            {tokenPercentage.map((item) => <Flex key={item}>
                <Button
    role="button"
    onClick={() => onPercentageSelect?.(parseInt(item))}
  >
                  <Text variant="body4" fontWeight="$medium">
                    {item}%
                  </Text>
                </Button>
              </Flex>)}
          </Flex>
        </Flex>}
    </Flex>;
}
