"use strict";
import { useQuery } from "@tanstack/react-query";
const VEABX_SUBGRAPH_URL = "https://subgraph.satsuma-prod.com/bdd23fa2967b/mss/veabx-4-testnet/api";
const GET_USER_LOCKS_QUERY = `
  query GetUserLocks($owner: String!) {
    veABXLocks(
      where: { owner: $owner }
      orderBy: lockStart
      orderDirection: desc
    ) {
      id
      owner
      amount
      lockEnd
      lockStart
      votingPower
      permanent
      managed
    }
  }
`;
const GET_VEABX_GLOBALS_QUERY = `
  query GetVeABXGlobals {
    veABXGlobals {
      id
      totalSupply
      totalPermanentLocked
    }
  }
`;
const GET_SINGLE_LOCK_QUERY = `
  query GetVeABXLock($id: String!) {
    veABXLock(id: $id) {
      id
      owner
      amount
      lockEnd
      lockStart
      votingPower
      permanent
      managed
    }
  }
`;
async function fetchDataFromSubgraph(query, variables = {}) {
  try {
    const response = await fetch(VEABX_SUBGRAPH_URL, {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify({
        query,
        variables
      })
    });
    if (!response.ok) {
      throw new Error(`HTTP error! status: ${response.status}`);
    }
    const data = await response.json();
    if (data.errors) {
      console.error("VeABX subgraph query errors:", data.errors);
      return null;
    }
    return data.data;
  } catch (error) {
    console.error("Failed to fetch veABX data:", error);
    return null;
  }
}
export function useVeABXUserLocks(owner, enabled = true) {
  return useQuery({
    queryKey: ["veabx-user-locks", owner?.toLowerCase()],
    queryFn: async () => {
      if (!owner) return [];
      const data = await fetchDataFromSubgraph(
        GET_USER_LOCKS_QUERY,
        { owner: owner.toLowerCase() }
      );
      return data?.veABXLocks || [];
    },
    enabled: enabled && !!owner,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
export function useVeABXGlobals(enabled = true) {
  return useQuery({
    queryKey: ["veabx-globals"],
    queryFn: async () => {
      const data = await fetchDataFromSubgraph(
        GET_VEABX_GLOBALS_QUERY
      );
      return data?.veABXGlobals || [];
    },
    enabled,
    refetchInterval: 6e4,
    // Refetch every minute
    staleTime: 3e4
    // Consider data stale after 30 seconds
  });
}
export function useVeABXLock(lockId, enabled = true) {
  return useQuery({
    queryKey: ["veabx-lock", lockId],
    queryFn: async () => {
      if (!lockId) return null;
      const data = await fetchDataFromSubgraph(
        GET_SINGLE_LOCK_QUERY,
        { id: lockId }
      );
      return data?.veABXLock || null;
    },
    enabled: enabled && !!lockId,
    refetchInterval: 3e4,
    // Refetch every 30 seconds
    staleTime: 15e3
    // Consider data stale after 15 seconds
  });
}
